INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p430549-ee466', 'stk-user1655', 'EE 466', 'info', '{"desc": "السلام عليكم ورحمة الله،،\n\nشباب اللي عنده كتاب كورس( EE 466 (Power System Protection\nوما يحتاجه ويود إنه يبيعه فأنا سأشتريه ولن يكون إن شاء الله بيننا خلاف في السعر…\n\nعندي كو أب الآن وأحتاج الكتاب علما بأني لم آخذ الكورس بعد\nأرسل على الخاص وإن شاء الله نتفق\nسلام", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee466/75427/1", "user": "user1655", "ts": 1247536742000, "tid": 75427, "pn": 1}}', 1247536742000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p491863-ee466', 'stk-x_zero', 'EE 466', 'info', '{"desc": "السلام عليكم\nشباب مثل ما انتم ملاحظين الدكتور ما يعرف يشرح ولا يقدر يوصل المعلومة\nوانا رايح فيها\nكم مرة افتح الكتاب والقاه يعقدني اكثر\nالكتاب مرررة ما يساعد هو معقد\nوالاختبار الاحد\nانا واربعة من اخوياي منعدمين ما ندري من وين نبدا نحاول نفهم مع الدكتور نحاول نفهم المادة عجزنا\nودي اعرف كيف تذاكرون واذا فيه نوتات تساعدني الله لا يهينكم علموني وش هي\nجزاكم الله خير", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee466/80057/1", "user": "X_zErO", "ts": 1258034234000, "tid": 80057, "pn": 1}}', 1258034234000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p492126-ee466', 'stk-dior', 'EE 466', 'info', '{"desc": "على فكره الدكتور راعي تشبيك\n\nوعطه جوه في الكلاس وابشر بالي يعزك\n\nوالفاينل 3-4 اسئله من ميجر 1 و ميجر 2 …يعني ذاكر اسئلة المياجر حقتك, وهو طبعا ما راح يعطيكم اوراق الاختبار بس انت حاول تصورها في الكلاس…\n\nوالجزء حق ال 463 حاول تذاكره من كتاب 463 (الكتاب مره واضح وسهل)", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee466/80057/5", "user": "Dior", "ts": 1258099148000, "tid": 80057, "pn": 5}}', 1258099148000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p574108-ee466', 'stk-the_right', 'EE 466', 'srcP', '{"html": "تفض أخي<br>هذا ميجر 1 محلول للدكتور الأمين<br><br>​<span data-fid=\"stk-f574108-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f574108-0": {"name": "ee466-major1-061.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/5e326c25080440350e49d5aae8e2cd86235f8705a99bde8224c213cca814126b"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/466-463/85965/4", "user": "The_Right", "ts": 1269543255000, "tid": 85965, "pn": 4}}', 1269543255000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
